INSERT INTO `motion_config` (`config_key`, `config_value`) VALUES ('profile', '{\"name\":\"Moch. Adam Athallahrich\",\"shortName\":\"ADAM.ATH\",\"roleTitle\":\"Fullstack Developer\",\"currentCompany\":\"PT. Sigma Cipta Caraka (Telkomsigma)\",\"birthInfo\":\"09 Mei 2001 · Surabaya\",\"location\":\"Malang / Indonesia\",\"bioId\":\"Rekayasa Perangkat Lunak dari SMK Telkom Malang yang saat ini berkarya sebagai Fullstack & Frontend Developer sekaligus Technical Researcher di PT. Sigma Cipta Caraka (Telkomsigma). Berfokus merancang aplikasi enterprise berskala besar, arsitektur frontend interaktif berbasis ekosistem Vue/Nuxt, sistem backend PHP/CodeIgniter/Laravel & database Oracle/MySQL, hingga aplikasi mobile Flutter & Android Native.\",\"phone\":\"+6285335769655\",\"email\":\"athallahrich@gmail.com\",\"instagram\":\"https://instagram.com/adamath_\",\"gitlab\":\"https://gitlab.com/athallahrich\",\"avatar\":\"/profile-pics/profile1.webp\"}') ON DUPLICATE KEY UPDATE `config_value` = VALUES(`config_value`);
