y\":\"mobile\",\"level\":65,\"dots\":3,\"logo\":\"\\/logos\\/java.svg\",\"experience\":\"POS App Diginov & Online Payment UI\",\"highlight\":\"Aplikasi kasir Android native dengan pelacakan stok bahan baku real-time\"},{\"name\":\"TailwindCSS & Buefy\",\"category\":\"frontend\",\"level\":90,\"dots\":4,\"logo\":\"\\/logos\\/tailwindcss-plain.svg\",\"experience\":\"Design System & Responsive Dashboard\",\"highlight\":\"Implementasi UI\\/UX responsif, komponen dashboard, dan animasi modern\"},{\"name\":\"AngularTS & .NET\",\"category\":\"fullstack\",\"level\":70,\"dots\":3,\"logo\":\"\\/logos\\/typescript-original.svg\",\"experience\":\"PT. Visionet Data Internasional (Meikarta App)\",\"highlight\":\"Admin dashboard AngularTS serta bug fixing & code review pada aplikasi .NET\"},{\"name\":\"Oracle, MySQL & SQL Server\",\"category\":\"fullstack\",\"level\":85,\"dots\":4,\"logo\":\"\\/logos\\/firebase-plain.svg\",\"experience\":\"Enterprise Database Operations (Telkomsigma & Visionet)\",\"highlight\":\"Operasional query kompleks menggunakan SSMS, Toad SQL, DBeaver & Navicat\"},{\"name\":\"HTML5, CSS3 & JavaScript\\/jQuery\",\"category\":\"frontend\",\"level\":90,\"dots\":5,\"logo\":\"\\/logos\\/html5-original.svg\",\"experience\":\"Web Standards & Interactive DOM Manipulation\",\"highlight\":\"Fondasi utama seluruh aplikasi web, landing page, dan sistem POS\"}]') ON DUPLICATE KEY UPDATE `config_value` = VALUES(`config_value`);
