-- 2. MOTION PROJECTS (5 Case Studies)
INSERT INTO `motion_projects` (`id`, `project_key`, `number`, `title`, `subtitle`, `company`, `period`, `category`, `roles`, `cover_image`, `logo`, `description`, `impact_highlights`, `tech_stack`, `team`, `live_url`, `repo_url`, `demo_credentials`, `gallery`, `display_order`, `is_active`) VALUES ('1', 'mango-hcm', '01', 'MANGO — Human Capital Management Online', 'Enterprise Organization Structure & Employee Ecosystem', 'PT. Sigma Cipta Caraka (Telkomsigma)', '2020 — Present', 'enterprise', '[\"frontend\",\"fullstack\"]', '/work/sigma/mango/dashboard.png', '/work/sigma/mango/logo.png', 'Aplikasi enterprise komprehensif untuk memetakan struktur organisasi perusahaan dari pucuk pimpinan (CEO) hingga seluruh lini jabatan di bawahnya, dilengkapi pengelolaan siklus hidup data karyawan, pengajuan & konfigurasi cuti (Leave Management), PCN, serta laporan kepegawaian.', '[\"Visualisasi interaktif Position Organization Chart & Position Tree Grid secara real-time.\",\"Sentralisasi data profil karyawan lengkap, riwayat jabatan, manajemen akses user, dan persetujuan PCN.\",\"Modul pengelolaan dan kuota cuti karyawan terintegrasi (Leave Dashboard & Config Leave).\"]', '[\"NuxtJS\",\"Vue.js\",\"Buefy\",\"JavaScript\",\"CSS3\",\"REST API\",\"Oracle \\/ MySQL\"]', '[\"Moch. Adam Athallahrich (Frontend\\/Fullstack)\",\"Mardi Jumari (Team Lead)\",\"Almaratus Sholicha (Backend)\"]', '', '', '', '[{\"title\":\"MANGO Executive Dashboard\",\"src\":\"\\/work\\/sigma\\/mango\\/dashboard.png\"},{\"title\":\"Position Organization Chart (Interactive Tree)\",\"src\":\"\\/work\\/sigma\\/mango\\/treeorgposition.png\"},{\"title\":\"Position Tree Grid View\",\"src\":\"\\/work\\/sigma\\/mango\\/treegridposition.png\"},{\"title\":\"Modal Edit Position & Hierarchy\",\"src\":\"\\/work\\/sigma\\/mango\\/modaleditposition.png\"},{\"title\":\"Complete Employee Detail & Background\",\"src\":\"\\/work\\/sigma\\/mango\\/employeedetail.png\"},{\"title\":\"Employee Directory Management\",\"src\":\"\\/work\\/sigma\\/mango\\/employee.png\"},{\"title\":\"Leave Management Dashboard\",\"src\":\"\\/work\\/sigma\\/mango\\/leavedashboard.png\"},{\"title\":\"Employee Leave Balance & Check\",\"src\":\"\\/work\\/sigma\\/mango\\/checkleaveemployee.png\"},{\"title\":\"Leave Configuration System\",\"src\":\"\\/work\\/sigma\\/mango\\/configleave.png\"},{\"title\":\"PCN Workflow Management\",\"src\":\"\\/work\\/sigma\\/mango\\/pcn.png\"},{\"title\":\"PCN Review & Approval\",\"src\":\"\\/work\\/sigma\\/mango\\/reviewpcn.png\"},{\"title\":\"Enterprise Master Data\",\"src\":\"\\/work\\/sigma\\/mango\\/masterdata.png\"},{\"title\":\"Analytics & HR Reporting\",\"src\":\"\\/work\\/sigma\\/mango\\/report.png\"},{\"title\":\"User & Role Access Management\",\"src\":\"\\/work\\/sigma\\/mango\\/usermanagement.png\"}]', '1', '1') ON DUPLICATE KEY UPDATE `project_key` = VALUES(`project_key`), `number` = VALUES(`number`), `title` = VALUES(`title`), `subtitle` = VALUES(`subtitle`), `company` = VALUES(`company`), `period` = VALUES(`period`), `category` = VALUES(`category`), `roles` = VALUES(`roles`), `cover_image` = VALUES(`cover_image`), `logo` = VALUES(`logo`), `description` = VALUES(`description`), `impact_highlights` = VALUES(`impact_highlights`), `tech_stack` = VALUES(`tech_stack`), `team` = VALUES(`team`), `live_url` = VALUES(`live_url`), `repo_url` = VALUES(`repo_url`), `demo_credentials` = VALUES(`demo_credentials`), `gallery` = VALUES(`gallery`), `display_order` = VALUES(`display_order`), `is_active` = VALUES(`is_active`);
INSERT INTO `motion_projects` (`id`, `project_key`, `number`, `title`, `subtitle`, `company`, `period`, `category`, `roles`, `cover_image`, `logo`, `description`, `impact_highlights`, `tech_stack`, `team`, `live_url`, `repo_url`, `demo_credentials`, `gallery`, `display_order`, `is_active`) VALUES ('2', 'sigma-pa', '02', 'PA — Performance Appraisal & Bukusaku', 'KPI-Based Annual Employee Assessment Platform', 'PT. Sigma Cipta Caraka (Telkomsigma)', '2020 — Present', 'enterprise', '[\"fullstack\",\"frontend\"]', '/work/sigma/pa/dashboard.png', '/work/sigma/pa/logo.png', 'Sistem penilaian kinerja tahunan karyawan (Performance Appraisal) yang berjalan sesuai periode aktual korporasi untuk memantau perkembangan kompetensi karyawan berdasarkan indikator KPI yang dinilai berjenjang oleh atasan (Supervisor/Manager).', '[\"Alur penilaian berjenjang antara karyawan dan supervisor berdasarkan bobot KPI terukur.\",\"Dashboard monitoring status penilaian, rekapitulasi nilai akhir, dan histori performa.\",\"Manajemen System Master, daftar pengguna PA, dan ekspor laporan evaluasi tahunan.\"]', '[\"CodeIgniter 3\",\"PHP Native\",\"HTML5\",\"CSS3\",\"JavaScript\",\"jQuery\",\"Oracle \\/ MySQL\"]', '[\"Moch. Adam Athallahrich (Fullstack Developer)\",\"Mardi Jumari (Team Lead)\",\"Anindyka Elras Saputri (Backup)\"]', '', '', '', '[{\"title\":\"Performance Appraisal Dashboard\",\"src\":\"\\/work\\/sigma\\/pa\\/dashboard.png\"},{\"title\":\"Detail Penilaian KPI Karyawan\",\"src\":\"\\/work\\/sigma\\/pa\\/penilaianemployee.png\"},{\"title\":\"Halaman Evaluasi & Penilaian Supervisor\",\"src\":\"\\/work\\/sigma\\/pa\\/penilaianspv.png\"},{\"title\":\"Detail Matriks Performance Appraisal\",\"src\":\"\\/work\\/sigma\\/pa\\/detailpa.png\"},{\"title\":\"Daftar PA Karyawan\",\"src\":\"\\/work\\/sigma\\/pa\\/listpaemployee.png\"},{\"title\":\"Daftar PA Supervisor\",\"src\":\"\\/work\\/sigma\\/pa\\/listpaspv.png\"},{\"title\":\"Laporan Evaluasi Kinerja (PA Report)\",\"src\":\"\\/work\\/sigma\\/pa\\/listreport.png\"},{\"title\":\"Konfigurasi System Master PA\",\"src\":\"\\/work\\/sigma\\/pa\\/listsystemmaster.png\"},{\"title\":\"Manajemen Peserta & User PA\",\"src\":\"\\/work\\/sigma\\/pa\\/listuserpa.png\"}]', '2', '1') ON DUPLICATE KEY UPDATE `project_key` = VALUES(`project_key`), `number` = VALUES(`number`), `title` = VALUES(`title`), `subtitle` = VALUES(`subtitle`), `company` = VALUES(`company`), `period` = VALUES(`period`), `category` = VALUES(`category`), `roles` = VALUES(`roles`), `cover_image` = VALUES(`cover_image`), `logo` = VALUES(`logo`), `description` = VALUES(`description`), `impact_highlights` = VALUES(`impact_highlights`), `tech_stack` = VALUES(`tech_stack`), `team` = VALUES(`team`), `live_url` = VALUES(`live_url`), `repo_url` = VALUES(`repo_url`), `demo_credentials` = VALUES(`demo_credentials`), `gallery` = VALUES(`gallery`), `display_order` = VALUES(`display_order`), `is_active` = VALUES(`is_active`);
INSERT INTO `motion_projects` (`id`, `project_key`, `number`, `title`, `subtitle`, `company`, `period`, `category`, `roles`, `cover_image`, `logo`, `description`, `impact_highlights`, `tech_stack`, `team`, `live_url`, `repo_url`, `demo_credentials`, `gallery`, `display_order`, `is_active`) VALUES ('3', 'casier-coffeeshop', '03', 'Casier Coffee Shop POS', 'Web-Based Cafe Point of Sale & Order Management', 'Independent Fullstack Project', 'Production Web App', 'personal', '[\"fullstack\",\"frontend\"]', '/project-ss/coffeeshop/dashboard.png', '', 'Aplikasi web Point of Sale (POS) untuk operasional Coffee Shop yang memungkinkan kasir mencatat pesanan pelanggan dengan cepat serta menyediakan panel Admin untuk mengelola menu, transaksi, dan laporan penjualan harian.', '[\"Dual-role akses terpisah untuk Kasir (pencatatan transaksi cepat) dan Admin (manajemen menu & laporan).\",\"Antarmuka pemilihan menu interaktif dengan kalkulasi keranjang dan cetak struk instan.\",\"Tersedia secara live beserta repositori kode sumber terbuka di GitLab.\"]', '[\"CodeIgniter 3\",\"PHP\",\"JavaScript\",\"jQuery\",\"HTML5\",\"CSS3\",\"MySQL\"]', '[\"Moch. Adam Athallahrich (Fullstack Developer)\"]', 'https://sistempossederhana.my.id/coffeeshop', 'https://gitlab.com/athallahrich/coffeeshop', 'Kasir: kasir / Password1! · Admin: admin / Password1!', '[{\"title\":\"Casier Coffee Shop \\u2014 Dashboard & Order View\",\"src\":\"\\/project-ss\\/coffeeshop\\/dashboard.png\"}]', '3', '1') ON DUPLICATE KEY UPDATE `project_key` = VALUES(`project_key`), `number` = VALUES(`number`), `title` = VALUES(`title`), `subtitle` = VALUES(`subtitle`), `company` = VALUES(`company`), `period` = VALUES(`period`), `category` = VALUES(`category`), `roles` = VALUES(`roles`), `cover_image` = VALUES(`cover_image`), `logo` = VALUES(`logo`), `description` = VALUES(`description`), `impact_highlights` = VALUES(`impact_highlights`), `tech_stack` = VALUES(`tech_stack`), `team` = VALUES(`team`), `live_url` = VALUES(`live_url`),